{
  "story": "Successive halving allocates training budgets to competing trials. Each round promotes the top fraction, doubling their training resources until one victor remains.",
  "aha": {
    "stateId": "round-2",
    "observation": "Only the best performing trials from the previous round receive double resources."
  },
  "layout": {
    "preset": "stepper-card",
    "width": 640
  },
  "parts": [
    {
      "id": "rail",
      "kind": "step-rail",
      "bind": {
        "active": "inputs.stepIndex",
        "items": "variant.states"
      }
    },
    {
      "id": "pic",
      "kind": "fixed-picture",
      "bind": {
        "active": "inputs.stepIndex",
        "regions": "variant.regions",
        "values": "variant.states.readouts"
      }
    },
    {
      "id": "ghost",
      "kind": "previous-state-ghost",
      "bind": {
        "regions": "previous.regions"
      }
    },
    {
      "id": "readouts",
      "kind": "value-readout",
      "bind": {
        "values": "variant.states.readouts"
      }
    },
    {
      "id": "callout",
      "kind": "active-callout",
      "bind": {
        "reason": "variant.states.why",
        "target": "variant.states.calloutRegion",
        "text": "variant.states.sentence"
      }
    }
  ],
  "controls": [
    {
      "id": "stepIndex",
      "kind": "index",
      "label": "Round",
      "options": [
        "Round 1",
        "Round 2",
        "Final"
      ]
    },
    {
      "id": "resetBtn",
      "kind": "reset",
      "label": "Reset",
      "options": []
    }
  ],
  "data": {
    "variants": [
      {
        "label": "Successive Halving",
        "regions": [
          {
            "id": "pool",
            "label": "Active Trials",
            "values": ["Trial A", "Trial B", "Trial C", "Trial D"]
          },
          {
            "id": "promoted",
            "label": "Promoted Trials",
            "values": ["Trial A", "Trial C"]
          },
          {
            "id": "winner",
            "label": "Best Trial",
            "values": ["Trial A"]
          }
        ],
        "states": [
          {
            "id": "round-1",
            "label": "Round 1",
            "short": "Start",
            "sentence": "All four trials start with equal base training resources.",
            "why": "Initial evaluation across the full candidate set.",
            "active": ["pool"],
            "calloutRegion": "pool",
            "readouts": [
              {
                "id": "budget",
                "label": "Allocated Epochs",
                "value": "5"
              },
              {
                "id": "remaining",
                "label": "Active Count",
                "value": "4"
              }
            ]
          },
          {
            "id": "round-2",
            "label": "Round 2",
            "short": "Halve",
            "sentence": "The top half of trials advance and receive double training resources.",
            "why": "Promoting leaders filters out poor configurations early.",
            "active": ["promoted"],
            "calloutRegion": "promoted",
            "readouts": [
              {
                "id": "budget",
                "label": "Allocated Epochs",
                "value": "10"
              },
              {
                "id": "remaining",
                "label": "Active Count",
                "value": "2"
              }
            ]
          },
          {
            "id": "final",
            "label": "Final",
            "short": "Winner",
            "sentence": "The single best performing trial receives maximum training resources.",
            "why": "Focuses remaining budget on the top performer.",
            "active": ["winner"],
            "calloutRegion": "winner",
            "readouts": [
              {
                "id": "budget",
                "label": "Allocated Epochs",
                "value": "20"
              },
              {
                "id": "remaining",
                "label": "Active Count",
                "value": "1"
              }
            ]
          }
        ]
      }
    ]
  }
}
